window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-eeae4c0dfe722a81"]={"versions": [{"id": "FIG-eeae4c0dfe722a81", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (AUTOSAR M2/M3-Metamodell-Ausschnitt, <em>Manifest Specification</em>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der Bereitstellung und Kommunikationsanbindung von <strong>SOVD</strong> (<em>Service-Oriented Vehicle Diagnostics</em>, ASAM SOVD) in der AUTOSAR Adaptive Platform (Release R22-11).</li>\n<li><strong>Architektonische Einordnung:</strong></li>\n<li>Spezialisierung von <code>NonOsModuleInstantiation</code> zur softwareseitigen Instanziierung von SOVD-Funktionsbausteinen auf einer <em>Adaptive Machine</em>.</li>\n<li>Differenzierung zwischen internen Diagnose-Servern (<code>SovdServerInstantiation</code>) und fahrzeugzentralen/externen Diagnose-Gateways (<code>SovdGatewayInstantiation</code>).</li>\n<li>Abbildung der Netzwerk- und Transportschicht-Parametrierung (Ethernet, TCP/UDP-Endpoints, TLS-Absicherung) über AUTOSAR-Standardelemente (<code>CommunicationConnector</code>, <code>SecureComProps</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>SovdModuleInstantiation</code></strong> <em>(abstract, spezialisiert <code>NonOsModuleInstantiation</code>)</em>:</li>\n<li>Basisklasse aller SOVD-Instanzen im Manifest.</li>\n<li>Attribut: <code>nodeIdentifier: String [0..1]</code> – Eindeutiger logischer Bezeichner des SOVD-Knotens im Fahrzeugnetzwerk.</li>\n<li><strong><code>SovdServerInstantiation</code></strong> <em>(konkret, spezialisiert <code>SovdModuleInstantiation</code>)</em>:</li>\n<li>Repräsentiert einen lokalen SOVD-Server, der Diagnoseressourcen einer bestimmten Fahrzeugkomponente bereitstellt.</li>\n<li>Attribut: <code>componentQualifier: String [0..1]</code> – Bezeichner der diagnostizierten logischen/physischen Komponente gemäß SOVD-Spezifikation.</li>\n<li><strong><code>SovdGatewayInstantiation</code></strong> <em>(konkret, spezialisiert <code>SovdModuleInstantiation</code>)</em>:</li>\n<li>Repräsentiert das SOVD-Gateway, das externe REST-/WebSocket-Anfragen bündelt, terminiert und an interne Server/Subsysteme vermittelt.</li>\n<li><strong><code>SovdGatewayEthernetCredentials</code></strong> <em>(abstract)</em>:</li>\n<li>Basisstruktur für Netzwerkadressierungsdaten des Gateways.</li>\n<li>Attribute:</li>\n<li><code>ipv4Address: Ip4AddressString [0..1]</code></li>\n<li><code>ipv6Address: Ip6AddressString [0..1]</code></li>\n<li><code>udpPort: PositiveInteger [0..1]</code></li>\n<li><strong><code>SovdGatewayLocalEndpointTcpConfig</code></strong> <em>(konkret, spezialisiert <code>SovdGatewayEthernetCredentials</code>)</em>:</li>\n<li>Konfiguriert die lokalen TCP-Endpunkte des SOVD-Gateways.</li>\n<li>Attribut: <code>tcpPort: PositiveInteger [0..1]</code></li>\n<li><strong><code>SecureComProps</code></strong> <em>(abstract, Basisklasse: <code>ARElement</code>)</em> / <strong><code>TlsSecureComProps</code></strong> <em>(konkret)</em>:</li>\n<li>Sicherheitskonfiguration für verschlüsselte Kommunikationsverbindungen (TLS/DTLS).</li>\n<li><strong><code>CommunicationConnector</code></strong> <em>(abstract, Basisklasse: <code>Identifiable</code>)</em>:</li>\n<li>Physischer/logischer Netzanbindungspunkt.</li>\n<li>Attribute:</li>\n<li><code>createEcuWakeupSource: Boolean [0..1]</code></li>\n<li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code></li>\n<li><strong><code>EthernetCommunicationConnector</code></strong> <em>(konkret, spezialisiert <code>CommunicationConnector</code>)</em>:</li>\n<li>Spezifische Ethernet-Netzwerkankopplung.</li>\n<li>Attribute:</li>\n<li><code>maximumTransmissionUnit: PositiveInteger [0..1]</code></li>\n<li><code>neighborCacheSize: PositiveInteger [0..1]</code></li>\n<li><code>pathMtuEnabled: Boolean [0..1]</code></li>\n<li><code>pathMtuTimeout: TimeValue [0..1]</code></li>\n<li><strong><code>NetworkEndpoint</code></strong> <em>(konkret, Basisklasse: <code>Identifiable</code>)</em>:</li>\n<li>Spezifiziert IP-Ebene und Host-Konfiguration.</li>\n<li>Attribute:</li>\n<li><code>fullyQualifiedDomainName: String [0..1]</code></li>\n<li><code>priority: PositiveInteger [0..1]</code></li>\n<li><strong><code>ApApplicationEndpoint</code></strong> <em>(konkret, Basisklasse: <code>Identifiable</code>)</em>:</li>\n<li>Spezifischer Anwendungs-Endpunkt auf Socket-Ebene.</li>\n<li>Attribut: <code>priority: PositiveInteger [0..1]</code></li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen, Aggregationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SovdModuleInstantiation</code> $\\rightarrow$ <code>CommunicationConnector</code></strong>:</li>\n<li>Rolle <code>+communicationConnector</code>, Kardinalität <code>0..*</code> (navigierbare Assoziation). Verknüpft die SOVD-Instanz mit den zugrundeliegenden Kommunikationskanälen.</li>\n<li><strong><code>SovdModuleInstantiation</code> $\\rightarrow$ <code>SecureComProps</code></strong>:</li>\n<li>Rolle <code>+securePropsForTcp</code>, Kardinalität <code>0..1</code> (Sicherheitsprofil für TCP-Payload).</li>\n<li>Rolle <code>+securePropsForUdp</code>, Kardinalität <code>0..1</code> (Sicherheitsprofil für UDP-Discovery / Lightweight Messaging).</li>\n<li><strong><code>SovdGatewayInstantiation</code> $\\rightarrow$ <code>SecureComProps</code></strong>:</li>\n<li>Rolle <code>+securePropsForExternalComm</code>, Kardinalität <code>0..1</code> (Dediziertes TLS-Profil für die fahrzeugexterne Diagnoseschnittstelle).</li>\n<li><strong><code>SovdGatewayInstantiation</code> $\\blacktriangleright$ <code>SovdGatewayLocalEndpointTcpConfig</code></strong>:</li>\n<li>Rolle <code>+unicastCredentials</code>, Kardinalität <code>0..1</code> (Komposition/Besitzbeziehung). Definiert die konkreten lokalen IP- und Port-Bindungen des Gateways.</li>\n<li><strong><code>EthernetCommunicationConnector</code> $\\rightarrow$ <code>NetworkEndpoint</code></strong>:</li>\n<li>Rolle <code>+unicastNetworkEndpoint</code>, Kardinalität <code>0..*</code> (Assoziation zu IP-Netzwerk-Endpunkten).</li>\n<li><strong><code>EthernetCommunicationConnector</code> $\\blacktriangleright$ <code>ApApplicationEndpoint</code></strong>:</li>\n<li>Rolle <code>+apApplicationEndpoint</code>, Kardinalität <code>0..*</code> (Komposition von AUTOSAR-Adaptive-Applikations-Sockets).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein rein deklaratives Metamodell-Diagramm handelt, sind keine Laufzeit-Zustandsübergänge abgebildet. Für die Systemintegration bestimmt das Modell folgende Initialisierungs- und Kommunikationsabläufe:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[Externer SOVD-Client]</p>\n<p class=\"fig-p\">|</p>\n<p class=\"fig-p\">| 1. TCP Connect (IP/Port via SovdGatewayLocalEndpointTcpConfig)</p>\n<p class=\"fig-p\">v</p>\n<p class=\"fig-p\">[SovdGatewayInstantiation]</p>\n<p class=\"fig-p\">|</p>\n<p class=\"fig-p\">| 2. TLS Handshake (Validierung via securePropsForExternalComm / TlsSecureComProps)</p>\n<p class=\"fig-p\">v</p>\n<p class=\"fig-p\">[Authentifizierter Session-Kanal]</p>\n<p class=\"fig-p\">|</p>\n<p class=\"fig-p\">| 3. Routing anhand URI / nodeIdentifier / componentQualifier</p>\n<p class=\"fig-p\">+--------------------------------------------+</p>\n<p class=\"fig-p\">|                                            |</p>\n<p class=\"fig-p\">v (interne TCP/UDP-Kommunikation)            v</p>\n<p class=\"fig-p\">[SovdServerInstantiation A]               [SovdServerInstantiation B]</p>\n<p class=\"fig-p\">(abgesichert via securePropsForTcp/Udp)  (abgesichert via securePropsForTcp/Udp)</p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>Stack-Bootstrapping:</strong> Der Adaptive-Core wertet das Manifest aus, instanziiert den SOVD-Gateway-Daemon und bindet diesen an die via <code>+unicastCredentials</code> konfigurierte IP-Adresse und den <code>tcpPort</code>.</li>\n<li><strong>TLS-Terminierung am Gateway:</strong> Eingehende Client-Verbindungen werden über die in <code>+securePropsForExternalComm</code> referenzierten Zertifikate/Cipher-Suites (<code>TlsSecureComProps</code>) authentifiziert und entschlüsselt.</li>\n<li><strong>Dispatching:</strong> Das Gateway löst eingehende REST-/JSON-Anfragen über den Pfad auf:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zuordnung zur passenden <code>SovdServerInstantiation</code> via <code>nodeIdentifier</code> bzw. <code>componentQualifier</code>.</li>\n<li>Weiterleitung über die internen Endpunkte (<code>EthernetCommunicationConnector</code>), optional getrennt abgesichert über <code>securePropsForTcp</code>/<code>securePropsForUdp</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Konfiguration (TPS_MANI_01400, TPS_MANI_01401):</strong></li>\n<li>Entwickler müssen bei der Manifest-Erstellung entscheiden, ob ein Prozess als vollwertiges Gateway (<code>SovdGatewayInstantiation</code>) oder als reiner interner Server (<code>SovdServerInstantiation</code>) fungiert.</li>\n<li>Wenn <code>SovdGatewayInstantiation</code> verwendet wird, ist <code>unicastCredentials</code> zwingend für die statische Bereitstellung von IP/Port zu modellieren, falls kein dynamischer Service-Discovery-Mechanismus greift.</li>\n<li><strong>Security & Krypto-Stack-Integration:</strong></li>\n<li>Verlinkung auf <code>TlsSecureComProps</code> bedingt die Bereitstellung entsprechender Crypto-Treiber und Schlüssel im <em>Crypto Service Manager</em> (CSM / Key Storage Providers).</li>\n<li>Externe und interne Verbindungen können unterschiedliche Sicherheitsstufen besitzen (<code>securePropsForExternalComm</code> vs. <code>securePropsForTcp/Udp</code>).</li>\n<li><strong>Netzwerk-Stack-Bindung:</strong></li>\n<li><code>EthernetCommunicationConnector</code> erfordert zwingend konsistente MTU- (<code>maximumTransmissionUnit</code>) und Path-MTU-Konfigurationen (<code>pathMtuEnabled</code>, <code>pathMtuTimeout</code>), um IP-Fragmentierung bei großen diagnostischen JSON-/REST-Payloads zu verhindern.</li>\n<li>Die Zuordnung zu <code>ApApplicationEndpoint</code> bestimmt die Port-Mappings auf POSIX-Socket-Ebene für den generierten Applikations-Code.</li>\n</ul>"}, {"id": "FIG-555910f9c3304252", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (AUTOSAR M2/M3-Metamodell-Ausschnitt, <em>Manifest Specification</em>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der Bereitstellung und Kommunikationsanbindung von <strong>SOVD</strong> (<em>Service-Oriented Vehicle Diagnostics</em>, ASAM SOVD) in der AUTOSAR Adaptive Platform (Release R22-11).</li>\n<li><strong>Architektonische Einordnung:</strong></li>\n<li>Spezialisierung von <code>NonOsModuleInstantiation</code> zur softwareseitigen Instanziierung von SOVD-Funktionsbausteinen auf einer <em>Adaptive Machine</em>.</li>\n<li>Differenzierung zwischen internen Diagnose-Servern (<code>SovdServerInstantiation</code>) und fahrzeugzentralen/externen Diagnose-Gateways (<code>SovdGatewayInstantiation</code>).</li>\n<li>Abbildung der Netzwerk- und Transportschicht-Parametrierung (Ethernet, TCP/UDP-Endpoints, TLS-Absicherung) über AUTOSAR-Standardelemente (<code>CommunicationConnector</code>, <code>SecureComProps</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>SovdModuleInstantiation</code></strong> <em>(abstract, spezialisiert <code>NonOsModuleInstantiation</code>)</em>:</li>\n<li>Basisklasse aller SOVD-Instanzen im Manifest.</li>\n<li>Attribut: <code>nodeIdentifier: String [0..1]</code> – Eindeutiger logischer Bezeichner des SOVD-Knotens im Fahrzeugnetzwerk.</li>\n<li><strong><code>SovdServerInstantiation</code></strong> <em>(konkret, spezialisiert <code>SovdModuleInstantiation</code>)</em>:</li>\n<li>Repräsentiert einen lokalen SOVD-Server, der Diagnoseressourcen einer bestimmten Fahrzeugkomponente bereitstellt.</li>\n<li>Attribut: <code>componentQualifier: String [0..1]</code> – Bezeichner der diagnostizierten logischen/physischen Komponente gemäß SOVD-Spezifikation.</li>\n<li><strong><code>SovdGatewayInstantiation</code></strong> <em>(konkret, spezialisiert <code>SovdModuleInstantiation</code>)</em>:</li>\n<li>Repräsentiert das SOVD-Gateway, das externe REST-/WebSocket-Anfragen bündelt, terminiert und an interne Server/Subsysteme vermittelt.</li>\n<li><strong><code>SovdGatewayEthernetCredentials</code></strong> <em>(abstract)</em>:</li>\n<li>Basisstruktur für Netzwerkadressierungsdaten des Gateways.</li>\n<li>Attribute:</li>\n<li><code>ipv4Address: Ip4AddressString [0..1]</code></li>\n<li><code>ipv6Address: Ip6AddressString [0..1]</code></li>\n<li><code>udpPort: PositiveInteger [0..1]</code></li>\n<li><strong><code>SovdGatewayLocalEndpointTcpConfig</code></strong> <em>(konkret, spezialisiert <code>SovdGatewayEthernetCredentials</code>)</em>:</li>\n<li>Konfiguriert die lokalen TCP-Endpunkte des SOVD-Gateways.</li>\n<li>Attribut: <code>tcpPort: PositiveInteger [0..1]</code></li>\n<li><strong><code>SecureComProps</code></strong> <em>(abstract, Basisklassen: <code>ARElement</code>, <code>UploadableDesignElement</code>)</em> / <strong><code>TlsSecureComProps</code></strong> <em>(konkret)</em>:</li>\n<li>Sicherheitskonfiguration für verschlüsselte Kommunikationsverbindungen (TLS/DTLS). Qualifiziert als <code>UploadableDesignElement</code> für das Design- und Update-Management.</li>\n<li><strong><code>CommunicationConnector</code></strong> <em>(abstract, Basisklasse: <code>Identifiable</code>)</em>:</li>\n<li>Physischer/logischer Netzanbindungspunkt.</li>\n<li>Attribute:</li>\n<li><code>createEcuWakeupSource: Boolean [0..1]</code></li>\n<li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code></li>\n<li><strong><code>EthernetCommunicationConnector</code></strong> <em>(konkret, spezialisiert <code>CommunicationConnector</code>)</em>:</li>\n<li>Spezifische Ethernet-Netzwerkankopplung.</li>\n<li>Attribute:</li>\n<li><code>maximumTransmissionUnit: PositiveInteger [0..1]</code></li>\n<li><code>neighborCacheSize: PositiveInteger [0..1]</code></li>\n<li><code>pathMtuEnabled: Boolean [0..1]</code></li>\n<li><code>pathMtuTimeout: TimeValue [0..1]</code></li>\n<li><strong><code>NetworkEndpoint</code></strong> <em>(konkret, Basisklasse: <code>Identifiable</code>)</em>:</li>\n<li>Spezifiziert IP-Ebene und Host-Konfiguration.</li>\n<li>Attribute:</li>\n<li><code>fullyQualifiedDomainName: String [0..1]</code></li>\n<li><code>priority: PositiveInteger [0..1]</code></li>\n<li><strong><code>ApApplicationEndpoint</code></strong> <em>(konkret, Basisklasse: <code>Identifiable</code>)</em>:</li>\n<li>Spezifischer Anwendungs-Endpunkt auf Socket-Ebene.</li>\n<li>Attribut: <code>priority: PositiveInteger [0..1]</code></li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen, Aggregationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SovdModuleInstantiation</code> $\\rightarrow$ <code>CommunicationConnector</code>:</strong></li>\n<li>Assoziation <code>+communicationConnector</code> (<code>0..*</code>): Weist der SOVD-Modulinstanz Netzwerk-Konnektoren der Machine zu.</li>\n<li><strong><code>SovdModuleInstantiation</code> $\\rightarrow$ <code>SecureComProps</code>:</strong></li>\n<li>Assoziation <code>+securePropsForTcp</code> (<code>0..1</code>): Sicherheitskonfiguration für interne TCP-Verbindungen.</li>\n<li>Assoziation <code>+securePropsForUdp</code> (<code>0..1</code>): Sicherheitskonfiguration für interne UDP-Verbindungen.</li>\n<li><strong><code>SovdGatewayInstantiation</code> $\\rightarrow$ <code>SecureComProps</code>:</strong></li>\n<li>Assoziation <code>+securePropsForExternalComm</code> (<code>0..1</code>): TLS-Sicherheitskonfiguration (<code>TlsSecureComProps</code>) für externe SOVD-Kommunikationskanäle.</li>\n<li><strong><code>SovdGatewayInstantiation</code> $\\rightarrow$ <code>SovdGatewayLocalEndpointTcpConfig</code>:</strong></li>\n<li>Komposition <code>+unicastCredentials</code> (<code>0..1</code>): Besitzt lokale TCP-Verbindungs- und Adressierungsdaten des Gateways.</li>\n<li><strong><code>EthernetCommunicationConnector</code> $\\rightarrow$ <code>NetworkEndpoint</code>:</strong></li>\n<li>Assoziation <code>+unicastNetworkEndpoint</code> (<code>0..*</code>): Referenziert IP-Endpunkte des Netzwerkinterfaces.</li>\n<li><strong><code>EthernetCommunicationConnector</code> $\\rightarrow$ <code>ApApplicationEndpoint</code>:</strong></li>\n<li>Komposition <code>+apApplicationEndpoint</code> (<code>0..*</code>): Aggregiert Socket-Endpunkte für Anwendungen.</li>\n<li><strong>Generalisierungs-Hierarchien:</strong></li>\n<li><code>SovdServerInstantiation</code> $\\rightarrow$ <code>SovdModuleInstantiation</code> $\\rightarrow$ <code>NonOsModuleInstantiation</code></li>\n<li><code>SovdGatewayInstantiation</code> $\\rightarrow$ <code>SovdModuleInstantiation</code> $\\rightarrow$ <code>NonOsModuleInstantiation</code></li>\n<li><code>SovdGatewayLocalEndpointTcpConfig</code> $\\rightarrow$ <code>SovdGatewayEthernetCredentials</code></li>\n<li><code>EthernetCommunicationConnector</code> $\\rightarrow$ <code>CommunicationConnector</code> $\\rightarrow$ <code>Identifiable</code></li>\n<li><code>TlsSecureComProps</code> $\\rightarrow$ <code>SecureComProps</code> $\\rightarrow$ <code>ARElement</code>, <code>UploadableDesignElement</code></li>\n<li><code>NetworkEndpoint</code> $\\rightarrow$ <code>Identifiable</code></li>\n<li><code>ApApplicationEndpoint</code> $\\rightarrow$ <code>Identifiable</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein rein deklaratives Metamodell-Diagramm handelt, sind keine Laufzeit-Zustandsübergänge abgebildet. Für die Systemintegration bestimmt das Modell folgende Initialisierungs- und Kommunikationsabläufe:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[Externer SOVD-Client]</p>\n<p class=\"fig-p\">|</p>\n<p class=\"fig-p\">| 1. TCP Connect (IP/Port via SovdGatewayLocalEndpointTcpConfig)</p>\n<p class=\"fig-p\">v</p>\n<p class=\"fig-p\">[SovdGatewayInstantiation]</p>\n<p class=\"fig-p\">|</p>\n<p class=\"fig-p\">| 2. TLS Handshake (Validierung via securePropsForExternalComm / TlsSecureComProps)</p>\n<p class=\"fig-p\">v</p>\n<p class=\"fig-p\">[Authentifizierter Session-Kanal]</p>\n<p class=\"fig-p\">|</p>\n<p class=\"fig-p\">| 3. Routing anhand URI / nodeIdentifier / componentQualifier</p>\n<p class=\"fig-p\">+--------------------------------------------+</p>\n<p class=\"fig-p\">|                                            |</p>\n<p class=\"fig-p\">v (interne TCP/UDP-Kommunikation)            v</p>\n<p class=\"fig-p\">[SovdServerInstantiation A]               [SovdServerInstantiation B]</p>\n<p class=\"fig-p\">(abgesichert via securePropsForTcp/Udp)  (abgesichert via securePropsForTcp/Udp)</p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>Stack-Bootstrapping:</strong> Der Adaptive-Core wertet das Manifest aus, instanziiert den SOVD-Gateway-Daemon und bindet diesen an die via <code>+unicastCredentials</code> konfigurierte IP-Adresse und den <code>tcpPort</code>.</li>\n<li><strong>TLS-Terminierung am Gateway:</strong> Eingehende Client-Verbindungen werden über die in <code>+securePropsForExternalComm</code> referenzierten Zertifikate/Cipher-Suites (<code>TlsSecureComProps</code>) authentifiziert und entschlüsselt.</li>\n<li><strong>Dispatching:</strong> Das Gateway löst eingehende REST-/JSON-Anfragen über den Pfad auf:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zuordnung zur passenden <code>SovdServerInstantiation</code> via <code>nodeIdentifier</code> bzw. <code>componentQualifier</code>.</li>\n<li>Weiterleitung über die internen Endpunkte (<code>EthernetCommunicationConnector</code>), optional getrennt abgesichert über <code>securePropsForTcp</code>/<code>securePropsForUdp</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Konfiguration (TPS_MANI_01400, TPS_MANI_01401):</strong></li>\n<li>Entwickler müssen bei der Manifest-Erstellung entscheiden, ob ein Prozess als vollwertiges Gateway (<code>SovdGatewayInstantiation</code>) oder als reiner interner Server (<code>SovdServerInstantiation</code>) fungiert.</li>\n<li>Wenn <code>SovdGatewayInstantiation</code> verwendet wird, ist <code>unicastCredentials</code> zwingend für die statische Bereitstellung von IP/Port zu modellieren, falls kein dynamischer Service-Discovery-Mechanismus greift.</li>\n<li><strong>Security & Krypto-Stack-Integration:</strong></li>\n<li>Verlinkung auf <code>TlsSecureComProps</code> bedingt die Bereitstellung entsprechender Crypto-Treiber und Schlüssel im <em>Crypto Service Manager</em> (CSM / Key Storage Providers).</li>\n<li>Externe und interne Verbindungen können unterschiedliche Sicherheitsstufen besitzen (<code>securePropsForExternalComm</code> vs. <code>securePropsForTcp/Udp</code>).</li>\n<li><strong>Netzwerk-Stack-Bindung:</strong></li>\n<li><code>EthernetCommunicationConnector</code> erfordert zwingend konsistente MTU- (<code>maximumTransmissionUnit</code>) und Path-MTU-Konfigurationen (<code>pathMtuEnabled</code>, <code>pathMtuTimeout</code>), um IP-Fragmentierung bei großen diagnostischen JSON-/REST-Payloads zu verhindern.</li>\n<li>Die Zuordnung zu <code>ApApplicationEndpoint</code> bestimmt die Port-Mappings auf POSIX-Socket-Ebene für den generierten Applikations-Code.</li>\n</ul>"}, {"id": "FIG-95dd614989bc744b", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (AUTOSAR M2/M3-Metamodell-Ausschnitt, <em>Manifest Specification</em>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der Bereitstellung und Kommunikationsanbindung von <strong>SOVD</strong> (<em>Service-Oriented Vehicle Diagnostics</em>, ASAM SOVD) in der AUTOSAR Adaptive Platform (Release R22-11).</li>\n<li><strong>Architektonische Einordnung:</strong></li>\n<li>Spezialisierung von <code>NonOsModuleInstantiation</code> zur softwareseitigen Instanziierung von SOVD-Funktionsbausteinen auf einer <em>Adaptive Machine</em>.</li>\n<li>Differenzierung zwischen internen Diagnose-Servern (<code>SovdServerInstantiation</code>) und fahrzeugzentralen/externen Diagnose-Gateways (<code>SovdGatewayInstantiation</code>).</li>\n<li>Abbildung der Netzwerk- und Transportschicht-Parametrierung (Ethernet, TCP/UDP-Endpoints, TLS-Absicherung) über AUTOSAR-Standardelemente (<code>CommunicationConnector</code>, <code>SecureComProps</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>SovdModuleInstantiation</code></strong> <em>(abstract, spezialisiert <code>NonOsModuleInstantiation</code>)</em>:</li>\n<li>Basisklasse aller SOVD-Instanzen im Manifest.</li>\n<li>Attribut: <code>nodeIdentifier: String [0..1]</code> – Eindeutiger logischer Bezeichner des SOVD-Knotens im Fahrzeugnetzwerk.</li>\n<li><strong><code>SovdServerInstantiation</code></strong> <em>(konkret, spezialisiert <code>SovdModuleInstantiation</code>)</em>:</li>\n<li>Repräsentiert einen lokalen SOVD-Server, der Diagnoseressourcen einer bestimmten Fahrzeugkomponente bereitstellt.</li>\n<li>Attribut: <code>componentQualifier: String [0..1]</code> – Bezeichner der diagnostizierten logischen/physischen Komponente gemäß SOVD-Spezifikation.</li>\n<li><strong><code>SovdGatewayInstantiation</code></strong> <em>(konkret, spezialisiert <code>SovdModuleInstantiation</code>)</em>:</li>\n<li>Repräsentiert das SOVD-Gateway, das externe REST-/WebSocket-Anfragen bündelt, terminiert und an interne Server/Subsysteme vermittelt.</li>\n<li><strong><code>SovdGatewayEthernetCredentials</code></strong> <em>(abstract)</em>:</li>\n<li>Basisstruktur für Netzwerkadressierungsdaten des Gateways.</li>\n<li>Attribute:</li>\n<li><code>ipv4Address: Ip4AddressString [0..1]</code></li>\n<li><code>ipv6Address: Ip6AddressString [0..1]</code></li>\n<li><code>udpPort: PositiveInteger [0..1]</code></li>\n<li><strong><code>SovdGatewayLocalEndpointTcpConfig</code></strong> <em>(konkret, spezialisiert <code>SovdGatewayEthernetCredentials</code>)</em>:</li>\n<li>Konfiguriert die lokalen TCP-Endpunkte des SOVD-Gateways.</li>\n<li>Attribut: <code>tcpPort: PositiveInteger [0..1]</code></li>\n<li><strong><code>SecureComProps</code></strong> <em>(abstract, Basisklassen: <code>ARElement</code>, <code>UploadableDesignElement</code>)</em> / <strong><code>TlsSecureComProps</code></strong> <em>(konkret)</em>:</li>\n<li>Sicherheitskonfiguration für verschlüsselte Kommunikationsverbindungen (TLS/DTLS). Qualifiziert als <code>UploadableDesignElement</code> für das Design- und Update-Management.</li>\n<li><strong><code>CommunicationConnector</code></strong> <em>(abstract, Basisklasse: <code>Identifiable</code>)</em>:</li>\n<li>Physischer/logischer Netzanbindungspunkt.</li>\n<li>Attribute:</li>\n<li><code>createEcuWakeupSource: Boolean [0..1]</code></li>\n<li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code></li>\n<li><strong><code>EthernetCommunicationConnector</code></strong> <em>(konkret, spezialisiert <code>CommunicationConnector</code>)</em>:</li>\n<li>Spezifische Ethernet-Netzwerkankopplung.</li>\n<li>Attribute:</li>\n<li><code>maximumTransmissionUnit: PositiveInteger [0..1]</code></li>\n<li><code>neighborCacheSize: PositiveInteger [0..1]</code></li>\n<li><code>pathMtuEnabled: Boolean [0..1]</code></li>\n<li><code>pathMtuTimeout: TimeValue [0..1]</code></li>\n<li><strong><code>NetworkEndpoint</code></strong> <em>(konkret, Basisklasse: <code>Identifiable</code>)</em>:</li>\n<li>Spezifiziert IP-Ebene und Host-Konfiguration.</li>\n<li>Attribute:</li>\n<li><code>fullyQualifiedDomainName: String [0..1]</code></li>\n<li><code>priority: PositiveInteger [0..1]</code></li>\n<li><strong><code>ApApplicationEndpoint</code></strong> <em>(konkret, Basisklasse: <code>Identifiable</code>)</em>:</li>\n<li>Spezifischer Anwendungs-Endpunkt auf Socket-Ebene.</li>\n<li>Attribut: <code>priority: PositiveInteger [0..1]</code></li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen, Aggregationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SovdModuleInstantiation</code> $\\rightarrow$ <code>CommunicationConnector</code>:</strong></li>\n<li>Assoziation <code>+communicationConnector</code> (<code>0..*</code>): Weist der SOVD-Modulinstanz Netzwerk-Konnektoren der Machine zu.</li>\n<li><strong><code>SovdModuleInstantiation</code> $\\rightarrow$ <code>SecureComProps</code>:</strong></li>\n<li>Assoziation <code>+securePropsForTcp</code> (<code>0..1</code>): Sicherheitskonfiguration für interne TCP-Verbindungen.</li>\n<li>Assoziation <code>+securePropsForUdp</code> (<code>0..1</code>): Sicherheitskonfiguration für interne UDP-Verbindungen.</li>\n<li><strong><code>SovdGatewayInstantiation</code> $\\rightarrow$ <code>SecureComProps</code>:</strong></li>\n<li>Assoziation <code>+securePropsForExternalComm</code> (<code>0..1</code>): TLS-Sicherheitskonfiguration (<code>TlsSecureComProps</code>) für externe SOVD-Kommunikationskanäle.</li>\n<li><strong><code>SovdGatewayInstantiation</code> $\\rightarrow$ <code>SovdGatewayLocalEndpointTcpConfig</code>:</strong></li>\n<li>Komposition <code>+unicastCredentials</code> (<code>0..1</code>): Besitzt lokale TCP-Verbindungs- und Adressierungsdaten des Gateways.</li>\n<li><strong><code>EthernetCommunicationConnector</code> $\\rightarrow$ <code>NetworkEndpoint</code>:</strong></li>\n<li>Assoziation <code>+unicastNetworkEndpoint</code> (<code>0..*</code>): Referenziert IP-Endpunkte des Netzwerkinterfaces.</li>\n<li><strong><code>EthernetCommunicationConnector</code> $\\rightarrow$ <code>ApApplicationEndpoint</code>:</strong></li>\n<li>Komposition <code>+apApplicationEndpoint</code> (<code>0..*</code>): Aggregiert Socket-Endpunkte für Anwendungen.</li>\n<li><strong>Generalisierungs-Hierarchien:</strong></li>\n<li><code>SovdServerInstantiation</code> $\\rightarrow$ <code>SovdModuleInstantiation</code> $\\rightarrow$ <code>NonOsModuleInstantiation</code></li>\n<li><code>SovdGatewayInstantiation</code> $\\rightarrow$ <code>SovdModuleInstantiation</code> $\\rightarrow$ <code>NonOsModuleInstantiation</code></li>\n<li><code>SovdGatewayLocalEndpointTcpConfig</code> $\\rightarrow$ <code>SovdGatewayEthernetCredentials</code></li>\n<li><code>EthernetCommunicationConnector</code> $\\rightarrow$ <code>CommunicationConnector</code> $\\rightarrow$ <code>Identifiable</code></li>\n<li><code>TlsSecureComProps</code> $\\rightarrow$ <code>SecureComProps</code> $\\rightarrow$ <code>ARElement</code>, <code>UploadableDesignElement</code></li>\n<li><code>NetworkEndpoint</code> $\\rightarrow$ <code>Identifiable</code></li>\n<li><code>ApApplicationEndpoint</code> $\\rightarrow$ <code>Identifiable</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein rein deklaratives Metamodell-Diagramm handelt, sind keine Laufzeit-Zustandsübergänge abgebildet. Für die Systemintegration bestimmt das Modell folgende Initialisierungs- und Kommunikationsabläufe:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[Externer SOVD-Client]</p>\n<p class=\"fig-p\">|</p>\n<p class=\"fig-p\">| 1. TCP Connect (IP/Port via SovdGatewayLocalEndpointTcpConfig)</p>\n<p class=\"fig-p\">v</p>\n<p class=\"fig-p\">[SovdGatewayInstantiation]</p>\n<p class=\"fig-p\">|</p>\n<p class=\"fig-p\">| 2. TLS Handshake (Validierung via securePropsForExternalComm / TlsSecureComProps)</p>\n<p class=\"fig-p\">v</p>\n<p class=\"fig-p\">[Authentifizierter Session-Kanal]</p>\n<p class=\"fig-p\">|</p>\n<p class=\"fig-p\">| 3. Routing anhand URI / nodeIdentifier / componentQualifier</p>\n<p class=\"fig-p\">+--------------------------------------------+</p>\n<p class=\"fig-p\">|                                            |</p>\n<p class=\"fig-p\">v (interne TCP/UDP-Kommunikation)            v</p>\n<p class=\"fig-p\">[SovdServerInstantiation A]               [SovdServerInstantiation B]</p>\n<p class=\"fig-p\">(abgesichert via securePropsForTcp/Udp)  (abgesichert via securePropsForTcp/Udp)</p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>Stack-Bootstrapping:</strong> Der Adaptive-Core wertet das Manifest aus, instanziiert den SOVD-Gateway-Daemon und bindet diesen an die via <code>+unicastCredentials</code> konfigurierte IP-Adresse und den <code>tcpPort</code>.</li>\n<li><strong>TLS-Terminierung am Gateway:</strong> Eingehende Client-Verbindungen werden über die in <code>+securePropsForExternalComm</code> referenzierten Zertifikate/Cipher-Suites (<code>TlsSecureComProps</code>) authentifiziert und entschlüsselt.</li>\n<li><strong>Dispatching:</strong> Das Gateway löst eingehende REST-/JSON-Anfragen über den Pfad auf:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zuordnung zur passenden <code>SovdServerInstantiation</code> via <code>nodeIdentifier</code> bzw. <code>componentQualifier</code>.</li>\n<li>Weiterleitung über die internen Endpunkte (<code>EthernetCommunicationConnector</code>), optional getrennt abgesichert über <code>securePropsForTcp</code>/<code>securePropsForUdp</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Konfiguration (TPS_MANI_01400, TPS_MANI_01401):</strong></li>\n<li>Entwickler müssen bei der Manifest-Erstellung entscheiden, ob ein Prozess als vollwertiges Gateway (<code>SovdGatewayInstantiation</code>) oder als reiner interner Server (<code>SovdServerInstantiation</code>) fungiert.</li>\n<li>Wenn <code>SovdGatewayInstantiation</code> verwendet wird, ist <code>unicastCredentials</code> zwingend für die statische Bereitstellung von IP/Port zu modellieren, falls kein dynamischer Service-Discovery-Mechanismus greift.</li>\n<li><strong>Security & Krypto-Stack-Integration:</strong></li>\n<li>Verlinkung auf <code>TlsSecureComProps</code> bedingt die Bereitstellung entsprechender Crypto-Treiber und Schlüssel im <em>Crypto Service Manager</em> (CSM / Key Storage Providers).</li>\n<li>Externe und interne Verbindungen können unterschiedliche Sicherheitsstufen besitzen (<code>securePropsForExternalComm</code> vs. <code>securePropsForTcp/Udp</code>).</li>\n<li><strong>Netzwerk-Stack-Bindung:</strong></li>\n<li><code>EthernetCommunicationConnector</code> erfordert zwingend konsistente MTU- (<code>maximumTransmissionUnit</code>) und Path-MTU-Konfigurationen (<code>pathMtuEnabled</code>, <code>pathMtuTimeout</code>), um IP-Fragmentierung bei großen diagnostischen JSON-/REST-Payloads zu verhindern.</li>\n<li>Die Zuordnung zu <code>ApApplicationEndpoint</code> bestimmt die Port-Mappings auf POSIX-Socket-Ebene für den generierten Applikations-Code.</li>\n</ul>"}, {"id": "FIG-99d741c18b97f047", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (AUTOSAR M2/M3-Metamodell-Ausschnitt, <em>Manifest Specification</em>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der Bereitstellung und Kommunikationsanbindung von <strong>SOVD</strong> (<em>Service-Oriented Vehicle Diagnostics</em>, ASAM SOVD) in der AUTOSAR Adaptive Platform (Release R22-11).</li>\n<li><strong>Architektonische Einordnung:</strong></li>\n<li>Spezialisierung von <code>NonOsModuleInstantiation</code> zur softwareseitigen Instanziierung von SOVD-Funktionsbausteinen auf einer <em>Adaptive Machine</em>.</li>\n<li>Differenzierung zwischen internen Diagnose-Servern (<code>SovdServerInstantiation</code>) und fahrzeugzentralen/externen Diagnose-Gateways (<code>SovdGatewayInstantiation</code>).</li>\n<li>Abbildung der Netzwerk- und Transportschicht-Parametrierung (Ethernet, TCP/UDP-Endpoints, TLS-Absicherung) über AUTOSAR-Standardelemente (<code>CommunicationConnector</code>, <code>SecureComProps</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>SovdModuleInstantiation</code></strong> <em>(abstract, spezialisiert <code>NonOsModuleInstantiation</code>)</em>:</li>\n<li>Basisklasse aller SOVD-Instanzen im Manifest.</li>\n<li>Attribut: <code>nodeIdentifier: String [0..1]</code> – Eindeutiger logischer Bezeichner des SOVD-Knotens im Fahrzeugnetzwerk.</li>\n<li><strong><code>SovdServerInstantiation</code></strong> <em>(konkret, spezialisiert <code>SovdModuleInstantiation</code>)</em>:</li>\n<li>Repräsentiert einen lokalen SOVD-Server, der Diagnoseressourcen einer bestimmten Fahrzeugkomponente bereitstellt.</li>\n<li>Attribut: <code>componentQualifier: String [0..1]</code> – Bezeichner der diagnostizierten logischen/physischen Komponente gemäß SOVD-Spezifikation.</li>\n<li><strong><code>SovdGatewayInstantiation</code></strong> <em>(konkret, spezialisiert <code>SovdModuleInstantiation</code>)</em>:</li>\n<li>Repräsentiert das SOVD-Gateway, das externe REST-/WebSocket-Anfragen bündelt, terminiert und an interne Server/Subsysteme vermittelt.</li>\n<li><strong><code>SovdGatewayEthernetCredentials</code></strong> <em>(abstract)</em>:</li>\n<li>Basisstruktur für Netzwerkadressierungsdaten des Gateways.</li>\n<li>Attribute:</li>\n<li><code>ipv4Address: Ip4AddressString [0..1]</code></li>\n<li><code>ipv6Address: Ip6AddressString [0..1]</code></li>\n<li><code>udpPort: PositiveInteger [0..1]</code></li>\n<li><strong><code>SovdGatewayLocalEndpointTcpConfig</code></strong> <em>(konkret, spezialisiert <code>SovdGatewayEthernetCredentials</code>)</em>:</li>\n<li>Konfiguriert die lokalen TCP-Endpunkte des SOVD-Gateways.</li>\n<li>Attribut: <code>tcpPort: PositiveInteger [0..1]</code></li>\n<li><strong><code>SecureComProps</code></strong> <em>(abstract, Basisklassen: <code>ARElement</code>, <code>UploadableDesignElement</code>)</em> / <strong><code>TlsSecureComProps</code></strong> <em>(konkret)</em>:</li>\n<li>Sicherheitskonfiguration für verschlüsselte Kommunikationsverbindungen (TLS/DTLS). Qualifiziert als <code>UploadableDesignElement</code> für das Design- und Update-Management.</li>\n<li><strong><code>CommunicationConnector</code></strong> <em>(abstract, Basisklasse: <code>Identifiable</code>)</em>:</li>\n<li>Physischer/logischer Netzanbindungspunkt.</li>\n<li>Attribute:</li>\n<li><code>createEcuWakeupSource: Boolean [0..1]</code></li>\n<li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code></li>\n<li><strong><code>EthernetCommunicationConnector</code></strong> <em>(konkret, spezialisiert <code>CommunicationConnector</code>)</em>:</li>\n<li>Spezifische Ethernet-Netzwerkankopplung.</li>\n<li>Attribute:</li>\n<li><code>maximumTransmissionUnit: PositiveInteger [0..1]</code></li>\n<li><code>neighborCacheSize: PositiveInteger [0..1]</code></li>\n<li><code>pathMtuEnabled: Boolean [0..1]</code></li>\n<li><code>pathMtuTimeout: TimeValue [0..1]</code></li>\n<li><strong><code>NetworkEndpoint</code></strong> <em>(konkret, Basisklasse: <code>Identifiable</code>)</em>:</li>\n<li>Spezifiziert IP-Ebene und Host-Konfiguration.</li>\n<li>Attribute:</li>\n<li><code>fullyQualifiedDomainName: String [0..1]</code></li>\n<li><code>priority: PositiveInteger [0..1]</code></li>\n<li><strong><code>ApApplicationEndpoint</code></strong> <em>(konkret, Basisklasse: <code>Identifiable</code>)</em>:</li>\n<li>Spezifischer Anwendungs-Endpunkt auf Socket-Ebene.</li>\n<li>Attribut: <code>priority: PositiveInteger [0..1]</code></li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen, Aggregationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SovdModuleInstantiation</code> $\\rightarrow$ <code>CommunicationConnector</code>:</strong></li>\n<li>Assoziation <code>+communicationConnector</code> (<code>0..*</code>): Weist der SOVD-Modulinstanz Netzwerk-Konnektoren der Machine zu.</li>\n<li><strong><code>SovdModuleInstantiation</code> $\\rightarrow$ <code>SecureComProps</code>:</strong></li>\n<li>Assoziation <code>+securePropsForTcp</code> (<code>0..1</code>): Sicherheitskonfiguration für interne TCP-Verbindungen.</li>\n<li>Assoziation <code>+securePropsForUdp</code> (<code>0..1</code>): Sicherheitskonfiguration für interne UDP-Verbindungen.</li>\n<li><strong><code>SovdGatewayInstantiation</code> $\\rightarrow$ <code>SecureComProps</code>:</strong></li>\n<li>Assoziation <code>+securePropsForExternalComm</code> (<code>0..1</code>): TLS-Sicherheitskonfiguration (<code>TlsSecureComProps</code>) für externe SOVD-Kommunikationskanäle.</li>\n<li><strong><code>SovdGatewayInstantiation</code> $\\rightarrow$ <code>SovdGatewayLocalEndpointTcpConfig</code>:</strong></li>\n<li>Komposition <code>+unicastCredentials</code> (<code>0..1</code>): Besitzt lokale TCP-Verbindungs- und Adressierungsdaten des Gateways.</li>\n<li><strong><code>EthernetCommunicationConnector</code> $\\rightarrow$ <code>NetworkEndpoint</code>:</strong></li>\n<li>Assoziation <code>+unicastNetworkEndpoint</code> (<code>0..*</code>): Referenziert IP-Endpunkte des Netzwerkinterfaces.</li>\n<li><strong><code>EthernetCommunicationConnector</code> $\\rightarrow$ <code>ApApplicationEndpoint</code>:</strong></li>\n<li>Komposition <code>+apApplicationEndpoint</code> (<code>0..*</code>): Aggregiert Socket-Endpunkte für Anwendungen.</li>\n<li><strong>Generalisierungs-Hierarchien:</strong></li>\n<li><code>SovdServerInstantiation</code> $\\rightarrow$ <code>SovdModuleInstantiation</code> $\\rightarrow$ <code>NonOsModuleInstantiation</code></li>\n<li><code>SovdGatewayInstantiation</code> $\\rightarrow$ <code>SovdModuleInstantiation</code> $\\rightarrow$ <code>NonOsModuleInstantiation</code></li>\n<li><code>SovdGatewayLocalEndpointTcpConfig</code> $\\rightarrow$ <code>SovdGatewayEthernetCredentials</code></li>\n<li><code>EthernetCommunicationConnector</code> $\\rightarrow$ <code>CommunicationConnector</code> $\\rightarrow$ <code>Identifiable</code></li>\n<li><code>TlsSecureComProps</code> $\\rightarrow$ <code>SecureComProps</code> $\\rightarrow$ <code>ARElement</code>, <code>UploadableDesignElement</code></li>\n<li><code>NetworkEndpoint</code> $\\rightarrow$ <code>Identifiable</code></li>\n<li><code>ApApplicationEndpoint</code> $\\rightarrow$ <code>Identifiable</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein rein deklaratives Metamodell-Diagramm handelt, sind keine Laufzeit-Zustandsübergänge abgebildet. Für die Systemintegration bestimmt das Modell folgende Initialisierungs- und Kommunikationsabläufe:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[Externer SOVD-Client]</p>\n<p class=\"fig-p\">|</p>\n<p class=\"fig-p\">| 1. TCP Connect (IP/Port via SovdGatewayLocalEndpointTcpConfig)</p>\n<p class=\"fig-p\">v</p>\n<p class=\"fig-p\">[SovdGatewayInstantiation]</p>\n<p class=\"fig-p\">|</p>\n<p class=\"fig-p\">| 2. TLS Handshake (Validierung via securePropsForExternalComm / TlsSecureComProps)</p>\n<p class=\"fig-p\">v</p>\n<p class=\"fig-p\">[Authentifizierter Session-Kanal]</p>\n<p class=\"fig-p\">|</p>\n<p class=\"fig-p\">| 3. Routing anhand URI / nodeIdentifier / componentQualifier</p>\n<p class=\"fig-p\">+--------------------------------------------+</p>\n<p class=\"fig-p\">|                                            |</p>\n<p class=\"fig-p\">v (interne TCP/UDP-Kommunikation)            v</p>\n<p class=\"fig-p\">[SovdServerInstantiation A]               [SovdServerInstantiation B]</p>\n<p class=\"fig-p\">(abgesichert via securePropsForTcp/Udp)  (abgesichert via securePropsForTcp/Udp)</p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>Stack-Bootstrapping:</strong> Der Adaptive-Core wertet das Manifest aus, instanziiert den SOVD-Gateway-Daemon und bindet diesen an die via <code>+unicastCredentials</code> konfigurierte IP-Adresse und den <code>tcpPort</code>.</li>\n<li><strong>TLS-Terminierung am Gateway:</strong> Eingehende Client-Verbindungen werden über die in <code>+securePropsForExternalComm</code> referenzierten Zertifikate/Cipher-Suites (<code>TlsSecureComProps</code>) authentifiziert und entschlüsselt.</li>\n<li><strong>Dispatching:</strong> Das Gateway löst eingehende REST-/JSON-Anfragen über den Pfad auf:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zuordnung zur passenden <code>SovdServerInstantiation</code> via <code>nodeIdentifier</code> bzw. <code>componentQualifier</code>.</li>\n<li>Weiterleitung über die internen Endpunkte (<code>EthernetCommunicationConnector</code>), optional getrennt abgesichert über <code>securePropsForTcp</code>/<code>securePropsForUdp</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Konfiguration (TPS_MANI_01400, TPS_MANI_01401):</strong></li>\n<li>Entwickler müssen bei der Manifest-Erstellung entscheiden, ob ein Prozess als vollwertiges Gateway (<code>SovdGatewayInstantiation</code>) oder als reiner interner Server (<code>SovdServerInstantiation</code>) fungiert.</li>\n<li>Wenn <code>SovdGatewayInstantiation</code> verwendet wird, ist <code>unicastCredentials</code> zwingend für die statische Bereitstellung von IP/Port zu modellieren, falls kein dynamischer Service-Discovery-Mechanismus greift.</li>\n<li><strong>Security & Krypto-Stack-Integration:</strong></li>\n<li>Verlinkung auf <code>TlsSecureComProps</code> bedingt die Bereitstellung entsprechender Crypto-Treiber und Schlüssel im <em>Crypto Service Manager</em> (CSM / Key Storage Providers).</li>\n<li>Externe und interne Verbindungen können unterschiedliche Sicherheitsstufen besitzen (<code>securePropsForExternalComm</code> vs. <code>securePropsForTcp/Udp</code>).</li>\n<li><strong>Netzwerk-Stack-Bindung:</strong></li>\n<li><code>EthernetCommunicationConnector</code> erfordert zwingend konsistente MTU- (<code>maximumTransmissionUnit</code>) und Path-MTU-Konfigurationen (<code>pathMtuEnabled</code>, <code>pathMtuTimeout</code>), um IP-Fragmentierung bei großen diagnostischen JSON-/REST-Payloads zu verhindern.</li>\n<li>Die Zuordnung zu <code>ApApplicationEndpoint</code> bestimmt die Port-Mappings auf POSIX-Socket-Ebene für den generierten Applikations-Code.</li>\n</ul>"}], "trans": [{"from": "FIG-eeae4c0dfe722a81", "to": "FIG-555910f9c3304252", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>SecureComProps</code>: Metaklasse erbt nun zusätzlich von <code>UploadableDesignElement</code> (neben <code>ARElement</code>).</li>\n</ul>"}, {"from": "FIG-555910f9c3304252", "to": "FIG-95dd614989bc744b", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-95dd614989bc744b", "to": "FIG-99d741c18b97f047", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
